"""TEAM DATA PIPELINE: merge curated inputs, buyer copy, evidence and price proposals.
Run from any directory. Standard-library only. NEVER propagates sibling packing weights.
Edit evidence/selected.json, detail-notes.json, guides.json and market-observations.json first.
"""
import json,re,math
from pathlib import Path
R=Path(__file__).resolve().parents[1];E=R/'data/evidence'
def read(p):return json.loads(p.read_text())
rows=read(E/'selected.json');notes=read(E/'detail-notes.json');guides=read(E/'guides.json');images=read(R/'data/image-manifest.json');access=read(E/'jumia-access.json');market=read(R/'data/market-observations.json');lookup={i:m for m in market for i in m['ids']}
settings=read(R/'data/settings.json');out=[]
# Keep observed prices intact; floors and conversion are used ONLY by the planning scenario.
for r,im,search in zip(rows,images,access):
 assert r['id']==im['id']==search['id'],'Input order/ID mismatch'
 id=r['id'];n=notes.get(str(id));source=n.get('source_price_cny',r['source_price_cny']) if n else r['source_price_cny'];w=n['weight_g'] if n else None;cm=n['packing_cm'] if n else None
 carton=n.get('carton_cm') if n else None;carton_qty=n.get('carton_quantity') if n else None;carton_g=n.get('carton_weight_g') if n else None
 v=math.prod(cm)/settings['volumetric_divisor'] if cm else None;cw=max(w/1000,v or 0) if w else None
 if carton: v=math.prod(carton)/settings['volumetric_divisor']/carton_qty;cw=max(carton_g/1000,math.prod(carton)/settings['volumetric_divisor'])/carton_qty
 fee=round(cw*(settings['air_usd_kg']*settings['usd_ngn']+settings['clearing_ngn_kg']),2) if cw is not None else None
 conditions=('Conditional supplier-carton allocation; carton dimensions/gross weight divided by stated units' if carton else 'Conditional selected-unit dimensional scenario' if cm else 'Weight-only LOWER BOUND; packed volume unknown') if fee is not None else 'Pending credible selected-unit packing data; no researched fee assigned'
 conditions+=';20kg+consolidated Lagos air allocation, not an isolated-parcel quote. Additional cartons, repacking, chargeable rounding/minimums, duties/VAT, insurance, China transport and other fees and onward delivery beyond Lagos excluded/unconfirmed. Divisor6000 is a planning assumption. Current carrier acceptance/FX/quote required.'
 # Consumer-facing copy: one name/identity paragraph, benefits, then observed features and care.
 a,b,c=guides[r['group']];f=n['facts'] if n else r['facts'].replace('Design described by source title:','Design:');f=re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',f);parts=[r['name']+' is '+a+'.',b,f+' '+c]
 def wc():return len(re.findall(r"\b[\w’'-]+\b",' '.join(parts)))
 if wc()<150:parts[1]+=' Choose the option that fits the items you already own and the way you use them each day.'
 assert 150<=wc()<=200,(id,wc())
 sections=[dict(heading=h,text=t) for h,t in zip(['What the Product is?','What are the clear benefits of the Product','Features of the Product'],parts)]
 # Pack prices must remain whole-pack observations, never silently normalised as unit prices.
 j=lookup.get(id);price=max(5.2,source)*settings['cny_ngn']+max(2000,fee or 0);sale=math.ceil(price*1.25/100)*100;target=.12 if sale<5000 else .1 if sale<15000 else .08;compare=math.ceil(sale/(1-target)/100)*100
 p=dict(id=id,day='Day '+str(r['day']).zfill(2),day_number=r['day'],day_product_number=r['daily_number'],author='DAVE ADEX',name=r['name'],brand=r['brand'],brand_original_field=r['brand_original_field'],category='Office accessories',group=r['group'],kind='office',source_url=r['url'],catalogue_price_cny=r['source_price_cny'],source_price_cny=source,source_price_note='Rendered CNY option observation; final checkout/pack/MOQ unverified' if n and 'source_price_cny'in n else r['source_price_status'],source_display_note='Selected-option observation; quote before ordering' if n and 'source_price_cny'in n else 'Starting observation; selected unit/pack unverified',supplier_facts=f,supplier_detail=n,selected_variant=n['selected_variant'] if n else 'Exact colour, size, material, supplied unit/pack and accessories need confirmation',supplier_caveat=n['note'] if n else 'Catalogue title/card inspected; no selected-option technical/packing sheet captured. Confirm full contents and current price.',dispatch_claim=n.get('dispatch',r['dispatch_claim']) if n else r['dispatch_claim'],description_sections=sections,description_word_count=wc(),checked='2026-11-04',images=[dict(role='main',url=im['url'],local_path=im['local'],catalogue_dom_url=im['catalogue_dom_url'],provenance=im['provenance'])],image_archive_status='One actual supplier catalogue main image downloaded; selected variant/colour and first detail-gallery position unverified.',browser_status=im['inspection_kind'],shipping=dict(supplier_weight_g=w,supplier_package_cm=cm,supplier_carton_cm=carton,supplier_carton_weight_g=carton_g,supplier_carton_quantity=carton_qty,calculation_basis='Carton allocation' if carton else 'Selected-unit dimensions' if cm else 'Weight-only lower bound' if fee is not None else 'Pending',volumetric_kg=v,chargeable_kg_scenario=cw,estimated_ngn=fee,status='Conditional estimate' if fee is not None else 'Pending',conditions=conditions,rate_source=settings['freight_url']),jumia=dict(price_ngn=j['price_ngn'] if j else None,title=j['title'] if j else 'Comparison pending',match=j['match'] if j else 'Pending',note=j['note'] if j else 'No reliable priced context captured',source_url=j['url'] if j else None,search_url=search['url'],access=search,observed_at='2026-11-04',pack_quantity=j['pack_quantity'] if j else None,pack_description=j['pack_description'] if j else 'Pending',price_unit=j['price_unit'] if j else 'Pending'),planning=dict(source_floor_cny=5.2,shipping_floor_ngn=2000,sale_ngn=sale,compare_at_ngn=compare,discount_percent=round((1-sale/compare)*100,1),status='Draft proposal per unconfirmed supplier quoted unit/pack; not a historical/live offer, landed cost or profit guarantee'))
 out.append(p)
metadata=dict(title='Office accessories — Week1',author='DAVE ADEX',products=250,days=5,per_day=50,families=25,checked='2026-11-04',settings=settings,representative_detail_pages=len(notes),conditional_freight=sum(x['shipping']['estimated_ngn'] is not None for x in out),pending_freight=sum(x['shipping']['estimated_ngn'] is None for x in out),priced_jumia_context=sum(x['jumia']['price_ngn'] is not None for x in out),identical_verified_jumia=0)
(R/'data/products.json').write_text(json.dumps(dict(metadata=metadata,products=out),ensure_ascii=False,indent=2));print('Assembled',len(out),'freight',metadata['conditional_freight'],'pending',metadata['pending_freight'],'words',min(x['description_word_count'] for x in out),max(x['description_word_count'] for x in out))
